package fileutil

import (
	"io/ioutil"
	"os"
)

// ReadBytes reads all bytes from a file.
func ReadBytes(path string) ([]byte, error) {
	return ioutil.ReadFile(path)
}

// WriteBytes writes bytes to a file with 0644 permissions.
func WriteBytes(path string, data []byte) error {
	return ioutil.WriteFile(path, data, 0644)
}

// TempFile creates a temporary file in dir with the given pattern.
func TempFile(dir, pattern string) (*os.File, error) {
	return ioutil.TempFile(dir, pattern)
}

// NopCloser wraps a reader with a no-op Close method.
func NopCloser(r interface{ Read([]byte) (int, error) }) interface {
	Read([]byte) (int, error)
	Close() error
} {
	return ioutil.NopCloser(r)
}

